//! @copydoc carb::tokens::registerPathAlias
//! @warning Deprecated: Use @ref carb::tokens::registerPathAlias instead.
inline void registerPathAlias(const char* alias, const char* value)
{
    tokens::registerPathAlias(alias, value);
}

//! @copydoc carb::tokens::unregisterPathAlias
//! @warning Deprecated: Use @ref carb::tokens::unregisterPathAlias instead.
inline void unregisterPathAlias(const char* alias)
{
    tokens::unregisterPathAlias(alias);
}

//! @copydoc carb::tokens::resolvePathAliases
//! @warning Deprecated: Use @ref carb::tokens::resolvePathAliases instead.
inline std::string resolvePathAliases(const char* srcBuf)
{
    return tokens::resolvePathAliases(srcBuf);
}

